package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.shipping.*;import com.intermarche.backoffice.domain.stock.*;import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.util.DateTimeProvider;import com.intermarche.backoffice.engine.stock.TemporalStockService;import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import io.restassured.response.Response;import jakarta.inject.Inject;import org.junit.jupiter.api.Test;import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static io.restassured.RestAssured.given;
@QuarkusTest @jakarta.enterprise.inject.Typed(ProductReturnWorkflowTest.class)
class ProductReturnWorkflowTest extends MissionCoordinationTest {
 @Inject TemporalStockService stocks;
 Response returns(String actor,String path,Object body){return given().auth().oauth2(actor).contentType("application/json").body(body).post("/product-returns"+path);}
 Map<String,Object> received(int qty){return returns(f.picker(),"",Map.of("storeId",f.store(),"productId",f.product(),"locationId",f.location(),"quantity",qty,"reference","CLIENT-1","reason","Produit retourné par le client","requestKey",key())).then().statusCode(200).extract().jsonPath().getMap("$");}
 Map<String,Object> decision(Map<String,Object> r,String state){long line=((Number)((List<Map<String,Object>>)r.get("lines")).getFirst().get("id")).longValue();return new LinkedHashMap<>(Map.of("storeId",f.store(),"returnId",r.get("id"),"lineId",line,"expectedRevision",r.get("revision"),"reason","Inspection physique effectuée","inspection",state,"requestKey",key()));}
 void stock(int physical,int usable){QuarkusTransaction.requiringNew().run(()->{var a=stocks.account(f.store(),f.product());var v=stocks.availability(a.id,null,DateTimeProvider.now());assertEquals(0,new BigDecimal(physical).compareTo(v.physical));assertEquals(0,new BigDecimal(usable).compareTo(v.eligiblePhysical));});}
 @Test void uninspectedReturnIsPhysicalButUnavailableAndReplayDoesNotReceiveTwice(){var input=Map.of("storeId",f.store(),"productId",f.product(),"locationId",f.location(),"quantity",3,"reference","CLIENT-1","reason","Retour scellé à inspecter","requestKey",key());returns(f.picker(),"",input).then().statusCode(200);returns(f.picker(),"",input).then().statusCode(200);stock(3,0);assertEquals(1,QuarkusTransaction.requiringNew().call(()->ProductReturn.count("store.id",f.store())));var wrong=new HashMap<String,Object>(input);wrong.put("storeId",f.other());wrong.put("requestKey",key());returns(f.picker(),"",wrong).then().statusCode(403);}
 @Test void inspectedGoodReturnMovesViaTransitThenRestocksOnce(){var r=received(3);r=returns(f.picker(),"/inspect",decision(r,"GOOD")).then().statusCode(200).extract().jsonPath().getMap("$");var plan=decision(r,"GOOD");plan.put("decision","RESTOCK");plan.put("locationId",f.location());plan.put("quantity",3);returns(f.picker(),"/dispositions",plan).then().statusCode(403);r=returns(f.manager(),"/dispositions",plan).then().statusCode(200).extract().jsonPath().getMap("$");var d=((List<Map<String,Object>>)((List<Map<String,Object>>)r.get("lines")).getFirst().get("dispositions")).getFirst();var move=new LinkedHashMap<String,Object>(Map.of("storeId",f.store(),"returnId",r.get("id"),"dispositionId",d.get("id"),"expectedRevision",r.get("revision"),"action","PICK","requestKey",key()));r=returns(f.picker(),"/execute",move).then().statusCode(200).extract().jsonPath().getMap("$");returns(f.picker(),"/execute",move).then().statusCode(200);stock(3,0);move.put("action","RECEIVE");move.put("requestKey",key());move.put("expectedRevision",r.get("revision"));returns(f.picker(),"/execute",move).then().statusCode(200).body("state",org.hamcrest.Matchers.is("COMPLETED"));returns(f.picker(),"/execute",move).then().statusCode(200);stock(3,3);}
 @Test void damagedReturnCannotRestockAndScrapIsManagerOnly(){var r=received(2);r=returns(f.picker(),"/inspect",decision(r,"DAMAGED")).then().statusCode(200).extract().jsonPath().getMap("$");var p=decision(r,"DAMAGED");p.put("decision","RESTOCK");p.put("locationId",f.location());p.put("quantity",2);returns(f.manager(),"/dispositions",p).then().statusCode(400);p.put("decision","SCRAP");p.put("requestKey",key());r=returns(f.manager(),"/dispositions",p).then().statusCode(200).extract().jsonPath().getMap("$");var d=((List<Map<String,Object>>)((List<Map<String,Object>>)r.get("lines")).getFirst().get("dispositions")).getFirst();var action=Map.of("storeId",f.store(),"returnId",r.get("id"),"dispositionId",d.get("id"),"expectedRevision",r.get("revision"),"action","PICK","requestKey",key());returns(f.picker(),"/execute",action).then().statusCode(403);returns(f.manager(),"/execute",action).then().statusCode(200);returns(f.manager(),"/execute",action).then().statusCode(200);stock(0,0);}
 @Test void splittingTheReturnKeepsTheUnorientedRemainderAndQuarantineUnavailable(){var r=received(4);r=returns(f.picker(),"/inspect",decision(r,"GOOD")).then().statusCode(200).extract().jsonPath().getMap("$");var p=decision(r,"GOOD");p.put("decision","QUARANTINE");p.put("locationId",f.location());p.put("quantity",2);r=returns(f.manager(),"/dispositions",p).then().statusCode(200).extract().jsonPath().getMap("$");var duplicate=decision(r,"GOOD");duplicate.put("decision","RESTOCK");duplicate.put("locationId",f.location());duplicate.put("quantity",3);returns(f.manager(),"/dispositions",duplicate).then().statusCode(400);var d=((List<Map<String,Object>>)((List<Map<String,Object>>)r.get("lines")).getFirst().get("dispositions")).getFirst();var action=new LinkedHashMap<String,Object>(Map.of("storeId",f.store(),"returnId",r.get("id"),"dispositionId",d.get("id"),"expectedRevision",r.get("revision"),"action","PICK","requestKey",key()));r=returns(f.picker(),"/execute",action).then().statusCode(200).extract().jsonPath().getMap("$");action.put("action","RECEIVE");action.put("expectedRevision",r.get("revision"));action.put("requestKey",key());returns(f.picker(),"/execute",action).then().statusCode(200).body("state",org.hamcrest.Matchers.is("TO_ORIENT"));stock(4,0);}
 @Test void pendingReturnCannotBeOrientedBeforeInspection(){var r=received(1);var p=decision(r,"GOOD");p.put("decision","RESTOCK");p.put("locationId",f.location());p.put("quantity",1);returns(f.manager(),"/dispositions",p).then().statusCode(400);stock(1,0);}

 @Test void pickerCanChooseOnlyLocationsOfThePermittedStore(){var places=given().auth().oauth2(f.picker()).get("/product-returns/locations?storeId="+f.store()+"&productId="+f.product()).then().statusCode(200).extract().jsonPath().getList("id");assertTrue(places.stream().anyMatch(v->Long.parseLong(v.toString())==f.location()));given().auth().oauth2(f.picker()).get("/product-returns/locations?storeId="+f.other()+"&productId="+f.product()).then().statusCode(403);}
}
